styles.css:
html, body {
    margin: 0 !important;

    /* needed to fix buggy vw/vh behavior in safari:
    https://stackoverflow.com/questions/25516934/safari-css-using-calc-with-vh-does-not-work
     */
    width: 100%;
    height: 100%;
}

body {
    font-size: 0.75rem;
    color: white;
    font-family: -apple-system,BlinkMacSystemFont,Segoe UI,Roboto,Oxygen,Ubuntu,Cantarell,Fira Sans,Droid Sans,Helvetica Neue,sans-serif;
}

#wrap {
    display: flex;
    align-items: center;
    justify-content: center;
}

.sprite {
    fill:yellow;
    stroke:#ccc;
    stroke-width: 0.1875rem;
}

canvas {
	image-rendering: optimizeSpeed;
	image-rendering: -moz-crisp-edges;
	image-rendering: -webkit-optimize-contrast;
	image-rendering: optimize-contrast;
	image-rendering: pixelated;
    -ms-interpolation-mode: nearest-neighbor;
}

#screen-back {
    background: #fcf7e4;
    height: calc(100% - 0.625rem);
    width: calc(100% - 0.625rem);
    position: absolute;
    z-index: -1;
    margin-left: auto;
    margin-right: auto;
    left: 0;
    right: 0;
    border-radius: 0.75rem;
    border: 0.3125rem solid #fcf7e4;
}

#screen {
    align-content: center;
    justify-content: center;
    align-items: center;
    height: 100vh;
}

.has-focus {
    border: 0.3125rem solid #96266c !important;
}

#paint-surface {
    position: absolute;
}

#paint-surface.borders {
    /* filter: drop-shadow(0px 0px 0.625rem #6B4F76) */
    border-right: 0.5rem inset #2f99a1;
    border-left: 0.5rem outset #2f99a1;
    border-top: 0.5rem outset #f290c1;
    border-bottom: 0.5rem inset #f290c1;
}

#paint-surface-container {
    text-align: center;
    /* messes up safari overflow-y: hidden; */
    width: 100%;
}

#debug-stats {
    position: absolute;
    bottom: 1.5%;
    left: 5%;
    color: #EABF0C;
    font-size: 0.6875rem;
    -webkit-user-select: none; /* Safari 3.1+ */
    -moz-user-select: none; /* Firefox 2+ */
    -ms-user-select: none; /* IE 10+ */
     user-select: none; /* Standard syntax */
}

.no-select {
    -webkit-touch-callout: none; /* iOS Safari */
    -webkit-user-select: none;   /* Chrome/Safari/Opera */
    -khtml-user-select: none;    /* Konqueror */
    -moz-user-select: none;      /* Firefox */
    -ms-user-select: none;       /* Internet Explorer/Edge */
    user-select: none;           /* Non-prefixed version, currently
                                    not supported by any browser */
}

.stats {
    margin-top: 0.5rem;
}

.blur .info {
    opacity: 0.2;
}

.just-screen #debug-stats,
.just-screen #screen-back,
.just-screen #controls,
.just-screen #instructions {
    display: none;
}

.just-screen #paint-surface-container {
    height: 100%;
    width: 100%;
}

.just-screen #paint-surface {
    border: none;
    position: relative;
}

.just-screen .paint-surface-spacer {
    flex-grow: 1;
}

/* ----- screen css ----- */
.game-embed {
    position: relative;
    left: 0.5rem;
    top: 0.5rem;
    width: calc(100% - 2rem);
    border: 0.5rem solid #EABF0C;
    background-color: #EABF0C;
    min-height: 58%;
    padding-bottom: 0.5rem;
    display: flex;
    align-items: center;
    justify-content: center;

    clip-path: polygon(0% 0.5rem, 0.5rem 0%, calc(100% - 0.5rem) 0%, 100% 0.5rem,
        100% calc(100% - 0.5rem), calc(100% - 0.5rem) 100%, 0.5rem 100%, 0 calc(100% - 0.5rem));
}

.hidden {
    display: none;
}

#game-screen {
    border: none;
    width: 100%;
    height: 100%;
    object-fit: fill;
    object-position: top;
}

.game-padmain {
    width: 96%;
    height: 100%;
    position: absolute;
    background: #EABF0C;
    border-radius: 1.25rem;
    display: flex;
    flex-direction: column;
}

.game-pad {
    width: 100%;
    height: 100%;
    position: absolute;
    display: flex;
    flex-direction: row;

}

.power-reset-part {
    height: 100%;
    position: absolute;
    display: flex;
    flex-direction: column;
    width: 1rem;
    left:95%;
}

.mygame-player {
    position: relative;
    width: calc(100% - 1rem);
    height: calc(70% - 1rem);
    background: #FFD41F;
    border-radius: 1.25rem;
    left: 0.5rem;
    top:0.5rem;

    /* left: calc((100% - 90%)/2);
    right: calc((100% - 90%)/2);
    top: 2%;    
    background: #FF0000;
    border-radius: 1.25rem;
    display: flex;
    flex-direction: column; */
}

.screen-boarder{
    position: relative;
    width: calc(100% - 2rem);
    min-height: 80%;
    background: #EABF0C;
    border-radius: 0.5rem;
    left: 1rem;

}

.game-reset:active button-more-people{
    fill: #D50000;
}

.game-power:active button-more-people{
    fill: #D50000;
}

.game-power{
    position: relative;
    width: 1rem;
    height: 5rem;
    top:20%;
    background-size: cover;
    border: none;
    background: transparent;
}

.game-power svg{
    display: block;
    margin: 0 auto;
    margin-top: 0.25rem;
    position: absolute;
    top: 0;
    left: 0;
    width: 0.6rem;
    height: 4rem;
    cursor:pointer;
}

.game-reset{
    position: relative;
    width: 1rem;
    height: 5rem;
    top:20%;
    background-size: cover;
    border: none;
    background: transparent;
}

.game-reset svg{
    display: block;
    margin: 0 auto;
    margin-top: 0.25rem;
    position: absolute;
    top: 0;
    left: 0;
    width: 0.6rem;
    height: 4rem;
    cursor:pointer;
}

/* .circle-pad{
    position: relative;
    left:35%;
    width: 1rem;
    height: 1rem;
    background: #EABF0C;
    border-radius: 0.5rem;
} */

.circle-left {
    position: absolute;
    left:40%;
    width: 1rem;
    height: 1rem;
    margin-top: 0.5rem;

    background: #EABF0C;
    border-radius: 0.5rem;
}

.circle-right {
    position: absolute;
    left:60%;
    width: 1rem;
    height: 1rem;
    margin-top: 0.5rem;

    background: #EABF0C;
    border-radius: 0.5rem;
}

.screen-display{
    position: absolute;
    background: #000;
    margin: 0.5rem;
    width: calc((100% - 1rem));;
    height: calc((100% - 1rem));;
    display: flex;
    align-items: center;
    justify-content: center;
}

.game-toppad{
    /* position: relative;
    left: 1rem;
    top: 1rem;

    width: calc(90%);
    height: 2rem;
    background: #EABF0C;
    display: flex;
    flex-direction: row; */


    position: relative;
    width: calc(100% - 2rem);
    height: 10%;

    border-radius: 1.25rem;
    left: 1rem;
    display: flex;
    flex-direction: row;
    /* background:red; */
}

.game-bottompad{
    /* position: relative;
    left: 1rem;
    top: 1rem;

    width: calc(90%);
    height: 2rem;
    background: #EABF0C;
    display: flex;
    flex-direction: row; */


    position: relative;
    width: calc(100% - 2rem);
    border-radius: 0.5rem;
    height: 10%;
    left: 1rem;
    bottom: 0rem;
    display: flex;
    flex-direction: row;
    /* background: red; */
}


.game-leftmenu svg {
    width: 100%;
    height: 40%;
}

.game-leftmenu{
    position: relative;
    width: 48%;
    height: 100%;
    border: none;
    background: transparent;
    cursor:pointer;

    /* background-image:url(data:image/svg+xml;base64,); */
}

.game-rightmenu{
    position: relative;
    width: 48%;
    height: 100%;
    left: 4%;
    border: none;
    background: transparent;
    cursor:pointer;

}

.game-rightmenu svg {
    width: 100%;
    height: 40%;
}

.game-ctllayer{
    position: relative;
    width: 100%;
    height: 30%;
    top:1rem;
    display: flex;
    flex-direction: row;
    background: #FFD41F;
    border-bottom-left-radius: 1.25rem;;
    border-bottom-right-radius: 1.25rem;
    /* background: red; */

}

button {
    outline: none;
}

/* .game-joysticklayer img{
    max-width: 100%;
    max-height: 100%;
    vertical-align: middle;
}  */

.game-joysticklayer{
    position: absolute;

    width: 40%;
    height: 28%;
    bottom: 1%;
    left:5%;
    background-repeat: no-repeat;
    content: "";
    background-size: contain;
    background-position: center;   
}

