    width: 100%;
    height: 100%;
}

.game-buttonlayer svg{
    width: 100%;
    height: 100%;
}

.game-logo{
    position: relative;
    background-repeat: no-repeat;
    height: 1.4rem;
    width: 4.5rem;
    background-size: contain;
    display: inline-block;
    margin: auto;
    margin-left: 0rem;
    content: "";
    background-image:url(data:image/svg+xml;base64,);


}

.game-player-background {
    text-align: center;
    width: 100%;
    height: 52%;
    bottom: 0rem;
    background: #FFD41F;
    border-radius: 0 0 1.25rem 1.25rem;
    z-index: 1;
    flex-shrink: 1;
}

.game-player-logo, .game-player-msft {
    position: absolute;
    width: 100%;
