    display: flex;
    flex-direction: column;
    height: 35%;
    width: 50%;
    position: absolute;
    left: 0;
    bottom: 0;

    touch-action: none;
    z-index: 20;

    transition: opacity 0.2s;

    max-width: 40%;
    background: #FFD41F;
}

.game-joystick-svg {
    width: 100%;
    height: initial;
}

/* ----- buttons css ----- */

.game-buttons {
    background: red;
    display: flex;
    flex-direction: column;

    height: 100%;
    width: 50%;
    position: absolute;
    right: 0;
    bottom: 0;

    z-index: 20;
    transition: opacity 0.2s;

    max-width: 40%;
}

.mygame-buttons{
    background: red;
    display: flex;
    flex-direction: column;

    height: 100%;
    width: 50%;
    position: absolute;
    right: 0;
    bottom: 0;

    z-index: 20;
    transition: opacity 0.2s;

    max-width: 40%; 
}

.game-button-svg {
    user-select: none;
    touch-action: none;
    margin-left: auto;
    background: green;
    height: 100%;

}

.game-sys-button {
    color: #EABF0C;
    background-color: #EABF0C;
    text-align: center;
    margin-top: 0.25rem;
    padding: 0.25rem 1rem;
    border-radius: 4rem;
    border: 0.25rem solid #EABF0C;
    font-size: 1rem;
    user-select: none;

    display: inline-block;
    transition: opacity 0.2s;
}

.game-buttons svg text {
    fill: #EABF0C;
    stroke: #EABF0C;
    stroke-width: 0.4;
}

.game-joystickup {
    position: relative;
    width: 100%;
    height: 100%;
}

.game-joystickup svg{
    width: 100%;
    height: 100%;
}

.game-button-svg {
    width: 100%;
    height: 100%;
}

.game-joystick,
.game-sys-button,
.game-button-svg svg text {
    cursor: pointer;
}


.blur .game-joystick, .blur .game-buttons, .blur .game-sys-button {
    opacity: 0.3;
}

/**
* This covers the tablet/mobile view for the simulator where just the screen is shown
*/

/* 
===== Standard view 
*/
/* width constrained */
.game-player {
    width: 100vw;
    height: calc((20 / 14) * 100vw);
}
html {
    font-size: 4.5vw;
}
/* height constrained */
@media (min-aspect-ratio: 17 / 20) {
    .game-player {
        height: 100vh;
        width: calc(((17 / 20) * 100vh));
    }

    .game-pad {
        height: 100vh;
        width: calc(((17 / 20) * 100vh));
    }

    .game-padmain {
        height: 100vh;
        width: calc(((17 / 20) * 100vh - 1rem)  );

    }

    .game-power{
        position: relative;
        width: 1rem;
        height: 5rem;
        top:20%;
        border: none;
        background-size: cover;
        background: transparent;
    }
    .game-reset{
        position: relative;
        width: 1rem;
        height: 5rem;
        top:20%;
        background-size: cover;
        border: none;
        background: transparent;
    }


    html {
        /* font-size: calc((17 / 20) * 4.5vh) */
        /* calc + vw/vh + font-size is buggy in Safari */
        font-size: 3.825vh; 
    }
}
/* 
===== Landscape view
(always height constrained)
*/
@media (min-aspect-ratio: 2/1) and (min-width: 250px) and (min-height: 200px)  {
    .game-player {
        width: 100%;
        height: 100%;
        max-width: 300vh;
    }

    .game-toppad {
        height: 0px;
    }

    .game-pad {
        width: 100%;
        height: 100%;
        max-width: 300vh;
    }

    .game-padmain {
        width: 100%;
        height: 100%;
        max-width: 300vh;
    }

    .game-joysticklayer{    
        width: calc((100vw - 130vh - 15vh)/2);
        height: calc((100vw - 130vh - 15vh )/2);
        max-width: 60vh;
        max-height: 60vh;
        bottom: 5rem;
        left: 3vh;
    }

    .game-buttonlayer {    
        width: calc((100vw - 130vh - 15vh)/2);
        height: calc((100vw - 130vh - 15vh)/2);
        max-width: 60vh;
        max-height: 60vh;
        bottom: 5rem;
        right: 3vh;

    }

    .screen-boarder {
        height: 100%;
        max-height: 100%;
        width: 130vh;
        left: 0;
        top: 0;
        margin: auto;
        padding: 0;

        box-sizing: border-box;
        display: flex;
        align-items: center;
    }
    #game-screen {
        object-position: unset;
    }
    .game-ctllayer {
        height: 0px;
    }

    .mygame-player {
        position: relative;
        width: calc(100% - 1rem);
        height: calc(100% - 1rem);
        /* background: #FFD41F; */
        border-radius: 1.25rem;
        left: 0.5rem;
        top:0.5rem;
        /* left: calc((100% - 90%)/2);
        right: calc((100% - 90%)/2);
        top: 2%;    
        background: #FF0000;
        border-radius: 1.25rem;
        display: flex;
        flex-direction: column; */
    }

    .game-player-msft {
        display: none;
    }

    .game-bottompad {
        position: fixed;
        top: 1rem;
        left: calc(50% + 100vh - 35vh);
        width: 35vh;
    }

    .game-reset{
        height: 0;
    }

    .game-reset svg{
        display: none;
    } 

    .game-power{
        height: 0;
    }

    .game-power svg{
        display: none;
    }

    .power-reset-part {
        display: none;
    }
}

/* 
===== Mini view (no controls)
*/
@media 
(max-width: 250px),
(max-height: 200px) {
    /* hide controls */
    .game-player-msft, .game-joysticklayer, .game-buttonlayer, .game-sys-button  .game-reset{
        display: none;
    }
    .game-embed {
        width: calc(100% - 2rem);
        height: calc(100% - 2rem);
        flex-grow: unset;
        padding-bottom: 0;
    }
    .game-ctllayer {
        height:0;
    }

    /* width constrained */
    .game-player {
        width: 100vw;
        height: calc((20 / 26) * 100vw);
    }

    .game-pad {
        width: 100vw;
        height: calc((20 / 26) * 100vw);
    }

    .game-padmain{
        width: 100vw;
        height: calc((20 / 26) * 100vw);   
     }
    .mygame-player{
        position: relative;
        width: calc(100% - 1rem);
        height: calc(100% - 1rem);
    }
    .game-reset{
        height: 0;
    }

    .game-reset svg{
        display: none;
    }

    .game-power{
        height: 0;
    }

    .game-power svg{
        display: none;
    }

    .power-reset-part {
        display: none;
    }

}
/* height constrained */
@media 
(max-width: 250px) and (min-aspect-ratio: 26 / 20),
(max-height: 200px) and (min-aspect-ratio: 26 / 20) {
    .game-player {
        height: 100vh;
        width: calc((26 / 20) * 100vh);
    }
    .game-pad {
        height: 100vh;
        width: calc((26 / 20) * 100vh);
    }
    .game-padmain{
        height: 100vh;
        width: calc((26 / 20) * 100vh); 
    }

    .mygame-player{
        position: relative;
        width: calc(100% - 1rem);
        height: calc(100% - 1rem);
    }

    .game-reset{
        height: 0;
    }

    .game-reset svg{
        display: none;
    }

    .power-reset-part {
        display: none;
    }

    .game-power{
        height: 0;
    }

    .game-power svg{
        display: none;
    }

    .game-ctllayer {
        height:0;
    }

    html {
        /* font-size: calc((26 / 20) * 4.5vh); */
        /* calc + vw/vh + font-size is buggy in Safari */
        font-size: 5.85vh;
    }
}

